const bullishText = $('Get Bullish CSV').first().json.data || '';
const bearishText = $('Get Bearish CSV').first().json.data || '';

function parseCSV(text) {
  if (!text) return [];
  const lines = text.split('\n').map(line => line.trim()).filter(line => line.length > 0);
  if (lines.length < 2) return [];

  const headers = lines[0].split(',').map(h => h.replace(/"/g, '').trim());
  const results = [];

  for (let i = 1; i < lines.length; i++) {
    const currentLine = lines[i].split(',').map(val => val.replace(/"/g, '').trim());
    if (currentLine.length < headers.length) continue;

    const row = {};
    headers.forEach((header, index) => {
      row[header] = currentLine[index];
    });
    results.push(row);
  }
  return results;
}

const bullishStocks = parseCSV(bullishText).slice(0, 5);
const bearishStocks = parseCSV(bearishText).slice(0, 5);

let message = '🔥 *Super Investing: Daily Momentum Updates* 🔥\n';
message += '📊 Track Live: [Momentum Dashboard](https://v0-stock-momentum-dashboard-three.vercel.app/)\n';
message += '━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n';

message += '📈 *TOP BULLISH MOMENTUM STOCKS* (Score: 7-10)\n';
message += '------------------------------------------\n';
if (bullishStocks.length > 0) {
  bullishStocks.forEach(s => {
    const change = parseFloat(s.Price_Change_Pct || '0');
    const changeText = change >= 0 ? `+${change.toFixed(1)}%` : `${change.toFixed(1)}%`;
    message += `🟢 *${s.Ticker}* | Score: *${parseFloat(s.Score).toFixed(1)}* (${s.Sentiment})\n`;
    message += `   ↳ Price: ₹${parseFloat(s.Close).toFixed(1)}\n`;
    message += `   ↳ Performance: *${changeText}* (since signal ${s.Days_Since_Signal} days ago)\n\n`;
  });
} else {
  message += 'No high momentum bullish stocks detected today.\n\n';
}

message += '📉 *TOP BEARISH MOMENTUM STOCKS* (Score: 0-4)\n';
message += '------------------------------------------\n';
if (bearishStocks.length > 0) {
  bearishStocks.forEach(s => {
    const change = parseFloat(s.Price_Change_Pct || '0');
    const changeText = change >= 0 ? `+${change.toFixed(1)}%` : `${change.toFixed(1)}%`;
    message += `🔴 *${s.Ticker}* | Score: *${parseFloat(s.Score).toFixed(1)}* (${s.Sentiment})\n`;
    message += `   ↳ Price: ₹${parseFloat(s.Close).toFixed(1)}\n`;
    message += `   ↳ Performance: *${changeText}* (since signal ${s.Days_Since_Signal} days ago)\n\n`;
  });
} else {
  message += 'No high momentum bearish stocks detected today.\n\n';
}

message += '💬 *Community Discussion*:\n';
const questions = [
  'Which of these momentum setups are you planning to trade tomorrow? Let us know! 👇',
  'Do you think the bullish trend in these stocks will continue this week? Vote in comments! 👇',
  'Are you holding any of these bearish stocks? Time to check your exit strategies! 👇',
  'Which sector looks strongest today based on these signals? Comment below! 👇'
];
const todaySeed = new Date().getDate();
const question = questions[todaySeed % questions.length];
message += `${question}\n`;

return [{ json: { message } }];
